/* From Uiverse.io by Tsiangana - Tags: simple, animation, loading, loader, text animation */
.__UIV_SCOPE__ .loader {
  font-family: Roboto, sans-serif;
  font-size: 25px;
  font-weight: 600;
}

.__UIV_SCOPE__ .ani:nth-child(1) {
